397→  /**
398→   * Resolve an IPNS name via the delegated routing API with retries.
399→   * Returns null if the IPNS name is not found (404).
400→   * Throws HttpException (BAD_GATEWAY) on routing failures.
401→   */
402→  private async resolveFromDelegatedRouting(ipnsName: string): Promise<{
403→    cid: string;
404→    sequenceNumber: string;
405→    signatureV2?: string;
406→    data?: string;
407→    pubKey?: string;
408→  } | null> {
409→    const url = `${this.delegatedRoutingUrl}/routing/v1/ipns/${ipnsName}`;
410→
411→    let lastError: Error | null = null;
412→
413→    for (let attempt = 0; attempt < this.maxRetries; attempt++) {
414→      try {
415→        const response = await fetch(url, {
416→          method: 'GET',
417→          headers: {
418→            Accept: 'application/vnd.ipfs.ipns-record',
419→          },
420→        });
421→
422→        // 404 means IPNS name not found - not an error
423→        if (response.status === 404) {
424→          this.logger.debug(`IPNS name not found: ${ipnsName}`);
425→          return null;
426→        }
427→
428→        if (response.ok) {
429→          // The delegated routing API returns the raw IPNS record
430→          // We need to parse it to extract the CID and sequence number
431→          const recordBytes = new Uint8Array(await response.arrayBuffer());
432→          const parsed = this.parseIpnsRecordBytes(recordBytes);
433→
434→          this.logger.debug(`IPNS name resolved successfully: ${ipnsName} -> ${parsed.cid}`);
435→          return parsed;
436→        }
437→
438→        // Handle rate limiting
439→        if (response.status === 429) {
440→          const retryAfter = response.headers.get('Retry-After');
441→          const delayMs = retryAfter
442→            ? parseInt(retryAfter, 10) * 1000
443→            : this.baseDelayMs * Math.pow(2, attempt);
444→
445→          this.logger.warn(`Rate limited on IPNS resolve, retrying in ${delayMs}ms`);
446→          await this.delay(delayMs);
447→          continue;
448→        }
449→
450→        // Non-retryable error
451→        // [SECURITY: MEDIUM-11] Log full error details but don't expose to client
452→        const errorText = await response.text();
453→        this.logger.error(
454→          `Delegated routing resolution returned ${response.status} for ${ipnsName}: ${errorText}`
455→        );
456→        throw new Error(`Delegated routing returned ${response.status}`);
457→      } catch (error) {
458→        // Re-throw HttpException immediately (e.g., parsing errors) - don't retry
459→        if (error instanceof HttpException) {
460→          throw error;
461→        }
462→
463→        lastError = error instanceof Error ? error : new Error(String(error));
464→
465→        // Only retry on network errors, not on HTTP errors
466→        if (
467→          lastError.message.includes('Delegated routing returned') &&
468→          !lastError.message.includes('429')
469→        ) {
470→          // [SECURITY: MEDIUM-11] Generic error message to avoid leaking internal details
471→          throw new HttpException(
472→            'Failed to resolve IPNS name from routing network',
473→            HttpStatus.BAD_GATEWAY
474→          );
475→        }
476→
477→        // Exponential backoff for network errors
478→        if (attempt < this.maxRetries - 1) {
479→          const delayMs = this.baseDelayMs * Math.pow(2, attempt);
480→          this.logger.warn(
481→            `IPNS resolve attempt ${attempt + 1} failed, retrying in ${delayMs}ms: ${lastError.message}`
482→          );
483→          await this.delay(delayMs);
484→        }
485→      }
486→    }
487→
488→    // [SECURITY: MEDIUM-11] Log full error, return generic message
489→    this.logger.error(
490→      `Failed to resolve IPNS name after ${this.maxRetries} attempts: ${lastError?.message}`
491→    );
492→    throw new HttpException(
493→      'Failed to resolve IPNS name from routing network after multiple attempts',
494→      HttpStatus.BAD_GATEWAY
495→    );
496→  }
497→
498→  /**
499→   * Parse an IPNS record to extract CID and sequence number
500→   * Uses inline protobuf decoder — no external dependencies
501→   */
502→  private parseIpnsRecordBytes(recordBytes: Uint8Array): {
503→    cid: string;
504→    sequenceNumber: string;
505→    signatureV2?: string;
506→    data?: string;
507→    pubKey?: string;
508→  } {
509→    try {
510→      const record = parseIpnsRecord(recordBytes);
511→
512→      // Extract CID from the Value field (format: /ipfs/<cid>)
513→      const valuePath = record.value;
514→      const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
515→      if (!cidMatch) {
516→        this.logger.error('Failed to extract CID from IPNS record value');
517→        throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
518→      }
519→
520→      const cid = cidMatch[1];
521→      const sequenceNumber = String(record.sequence ?? 0n);
522→
523→      // Base64-encode signature fields if present
524→      const signatureV2 = record.signatureV2
525→        ? Buffer.from(record.signatureV2).toString('base64')
526→        : undefined;
527→      const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
528→      const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;
529→
530→      this.logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
531→      return { cid, sequenceNumber, signatureV2, data, pubKey };
532→    } catch (error) {
533→      if (error instanceof HttpException) {
534→        throw error;
535→      }
536→      this.logger.error(`Failed to parse IPNS record: ${error}`);
537→      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
538→    }
539→  }
540→
541→  private delay(ms: number): Promise<void> {
542→    return new Promise((resolve) => setTimeout(resolve, ms));
543→  }
544→}
