 499→/**
 500→ * Add a file to a folder after successful upload (v2).
 501→ *
 502→ * Creates a FilePointer from the file's IPNS record and adds it to the folder's
 503→ * children array. Publishes both the file IPNS record and the updated folder
 504→ * metadata via a single batch API call.
 505→ *
 506→ * @param params.parentFolderState - Parent folder to add file to
 507→ * @param params.fileId - Pre-generated file UUID
 508→ * @param params.name - Original file name
 509→ * @param params.fileIpnsRecord - File IPNS record payload from createFileMetadata
 510→ * @returns Created file pointer and new sequence number
 511→ * @throws Error if name collision exists
 512→ */
 513→export async function addFileToFolder(params: {
 514→  parentFolderState: FolderNode;
 515→  fileId: string;
 516→  name: string;
 517→  fileIpnsRecord: FileIpnsRecordPayload;
 518→  ipnsPrivateKeyEncrypted: string;
 519→}): Promise<{ filePointer: FilePointer; newSequenceNumber: bigint }> {
 520→  // 1. Check for name collision
 521→  const nameExists = params.parentFolderState.children.some((c) => c.name === params.name);
 522→  if (nameExists) {
 523→    throw new Error('A file with this name already exists');
 524→  }
 525→
 526→  // 2. Create FilePointer (slim reference to per-file IPNS record + wrapped key)
 527→  const now = Date.now();
 528→  const filePointer: FilePointer = {
 529→    type: 'file',
 530→    id: params.fileId,
 531→    name: params.name,
 532→    fileMetaIpnsName: params.fileIpnsRecord.ipnsName,
 533→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
 534→    createdAt: now,
 535→    modifiedAt: now,
 536→  };
 537→
 538→  // 3. Add FilePointer to parent's children
 539→  const children: FolderChild[] = [...params.parentFolderState.children, filePointer];
 540→
 541→  // 4. Build folder IPNS record for batch publish
 542→  const folderResult = await buildFolderIpnsRecord({
 543→    children,
 544→    folderKey: params.parentFolderState.folderKey,
 545→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 546→    ipnsName: params.parentFolderState.ipnsName,
 547→    sequenceNumber: params.parentFolderState.sequenceNumber,
 548→  });
 549→
 550→  // 5. Batch publish: file IPNS record + folder IPNS record
 551→  const publishResult = await batchPublishIpnsRecords([
 552→    { ...params.fileIpnsRecord, recordType: 'file' },
 553→    folderResult.record,
 554→  ]);
 555→
 556→  if (publishResult.totalFailed > 0) {
 557→    console.error(
 558→      `Batch publish partial failure: ${publishResult.totalFailed}/${publishResult.totalFailed + publishResult.totalSucceeded} records failed`
 559→    );
 560→    throw new Error('Failed to publish one or more IPNS records');
 561→  }
 562→
 563→  return { filePointer, newSequenceNumber: folderResult.newSequenceNumber };
 564→}
 565→
 566→/**
 567→ * Add multiple files to a folder after successful upload (v2 batch).
 568→ *
 569→ * Creates FilePointer objects for all files, checks for name collisions,
 570→ * then publishes all N file IPNS records + 1 folder IPNS record via a
 571→ * single batch API call.
 572→ *
 573→ * @param params.parentFolderState - Parent folder to add files to
 574→ * @param params.files - Array of file data with pre-created IPNS records
 575→ * @returns Created file pointers and new sequence number
 576→ * @throws Error if any name collision exists
 577→ */
 578→export async function addFilesToFolder(params: {
 579→  parentFolderState: FolderNode;
 580→  files: Array<{
 581→    fileId: string;
 582→    name: string;
 583→    fileIpnsRecord: FileIpnsRecordPayload;
 584→    ipnsPrivateKeyEncrypted: string;
 585→  }>;
 586→}): Promise<{ filePointers: FilePointer[]; newSequenceNumber: bigint }> {
 587→  // 1. Build a set of existing child names for collision detection
 588→  const existingNames = new Set(params.parentFolderState.children.map((c) => c.name));
 589→
 590→  // 2. Create FilePointer for each file, checking collisions
 591→  const filePointers: FilePointer[] = [];
 592→  const now = Date.now();
 593→
 594→  for (const file of params.files) {
 595→    if (existingNames.has(file.name)) {
 596→      throw new Error(`A file with name "${file.name}" already exists`);
 597→    }
 598→    existingNames.add(file.name);
 599→
 600→    const filePointer: FilePointer = {
 601→      type: 'file',
 602→      id: file.fileId,
 603→      name: file.name,
 604→      fileMetaIpnsName: file.fileIpnsRecord.ipnsName,
 605→      ipnsPrivateKeyEncrypted: file.ipnsPrivateKeyEncrypted,
 606→      createdAt: now,
 607→      modifiedAt: now,
 608→    };
 609→    filePointers.push(filePointer);
 610→  }
 611→
 612→  // 3. Build updated children array
 613→  const children: FolderChild[] = [...params.parentFolderState.children, ...filePointers];
 614→
 615→  // 4. Build folder IPNS record
 616→  const folderResult = await buildFolderIpnsRecord({
 617→    children,
 618→    folderKey: params.parentFolderState.folderKey,
 619→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 620→    ipnsName: params.parentFolderState.ipnsName,
 621→    sequenceNumber: params.parentFolderState.sequenceNumber,
 622→  });
 623→
 624→  // 5. Batch publish: all N file IPNS records + 1 folder IPNS record (single API call)
 625→  const allRecords = [
 626→    ...params.files.map((f) => ({ ...f.fileIpnsRecord, recordType: 'file' as const })),
 627→    folderResult.record,
 628→  ];
 629→  const publishResult = await batchPublishIpnsRecords(allRecords);
 630→
 631→  if (publishResult.totalFailed > 0) {
 632→    console.error(
 633→      `Batch publish partial failure: ${publishResult.totalFailed}/${publishResult.totalFailed + publishResult.totalSucceeded} records failed`
 634→    );
 635→    throw new Error('Failed to publish one or more IPNS records');
 636→  }
 637→
 638→  return { filePointers, newSequenceNumber: folderResult.newSequenceNumber };
 639→}
